// Basic MOV Operations (QWORD)
mov rax, 0xDEADBEEF     // Immediate to Register
mov rbx, rax            // Register to Register
mov [rbp-8], rbx        // Register to Memory
mov rcx, [rsp+8]        // Memory to Register

// Data Size Awareness (MOV to 32-bit zero-extends to 64-bit automatically)
mov edx, 10             // Sets RDY upper 32 bits to zero

// Extended Moves (Crucial for explicit handling of smaller types)
movzx rsi, byte [rdi]   // Zero Extend (8-bit to 64-bit)
movsx r8, dword [rdi]   // Sign Extend (32-bit to 64-bit)

// Load Effective Address (Calculates address, puts result in register)
lea r9, [r10 + r11*4 + 16]

// Stack Operations
push rax                // RAX -> [RSP - 8]
pop rbx                 // [RSP] -> RBX; RSP += 8
